def parse_task_type(task_text):
    task_text = task_text.lower()
    if 'put' in task_text and 'in' in task_text:
        if 'two' in task_text or 'some' in task_text:
            return 'pick_two_obj'
        return 'put_obj'
    if 'heat' in task_text or 'hot' in task_text:
        return 'heat_obj'
    if 'cool' in task_text:
        return 'cool_obj'
    if 'clean' in task_text:
        return 'clean_obj'
    if 'look' in task_text or 'examine' in task_text:
        return 'look_obj'
    return 'general'

def hook(ctx, nb):
    task_text = ctx.get('task', {}).get('task', '')
    task_type = parse_task_type(task_text)
    nb['stage'] = 'find_target'
    nb['task_type'] = task_type
    nb['target_type'] = ctx.get('task', {}).get('target_type', '')
    nb['destination_type'] = ctx.get('task', {}).get('destination_type', '')
    nb['placed_count'] = 0
    nb['last_hint'] = ''
    nb['repeated_action_streak'] = 0
    nb['last_action'] = ''
    tool_hint = 'Focus on one subgoal at a time: find target, take it, transform if needed, go to destination, put it.'
    return {'skills': [{'text': 'Break tasks into stages: find, take, transform, go, put. Track what you have placed.'}], 'tool_hint': tool_hint}

def detect_loop(ctx, nb):
    action = ctx.get('action', {}).get('raw', '')
    if action == nb.get('last_action', ''):
        nb['repeated_action_streak'] = nb.get('repeated_action_streak', 0) + 1
    else:
        nb['repeated_action_streak'] = 0
    nb['last_action'] = action
    return nb['repeated_action_streak'] > 3

def update_stage(ctx, nb):
    action = ctx.get('action', {}).get('raw', '').lower()
    obs = ctx.get('observation', '').lower()
    inv = ctx.get('world', {}).get('inventory', [])
    task_type = nb.get('task_type', 'general')
    stage = nb.get('stage', 'find_target')

    if 'take' in action and nb.get('target_type', '') in obs:
        nb['stage'] = 'transform' if task_type in ['heat_obj', 'cool_obj', 'clean_obj'] else 'go_destination'
    elif 'heat' in action or 'cool' in action or 'clean' in action:
        nb['stage'] = 'go_destination'
    elif 'put' in action:
        nb['placed_count'] = nb.get('placed_count', 0) + 1
        if task_type == 'pick_two_obj' and nb['placed_count'] < 2:
            nb['stage'] = 'find_target'
        else:
            nb['stage'] = 'done'
    elif stage == 'find_target' and nb.get('target_type', '') in obs:
        nb['stage'] = 'take_target'
    return nb

def hook(ctx, nb):
    nb = update_stage(ctx, nb)
    is_loop = detect_loop(ctx, nb)
    if is_loop:
        stage = nb.get('stage', 'find_target')
        hint_map = {
            'find_target': 'Search locations systematically. Check common places for the target item.',
            'take_target': 'The target is visible. Take it from its location.',
            'transform': 'Apply the required transformation (heat/cool/clean) before proceeding.',
            'go_destination': 'Navigate to the destination location to place the item.',
            'put_target': 'Place the item at the destination.'
        }
        msg = 'Loop detected. ' + hint_map.get(stage, 'Try a different approach.')
        return {'kind': 'inject_hint', 'message': msg}
    return None

def get_stage_hint(nb, admissible):
    stage = nb.get('stage', 'find_target')
    task_type = nb.get('task_type', 'general')
    target = nb.get('target_type', '')
    dest = nb.get('destination_type', '')
    placed = nb.get('placed_count', 0)

    if stage == 'find_target':
        if task_type == 'pick_two_obj' and placed >= 1:
            return 'Find another ' + target + ' to place. Check locations you have not fully searched.'
        return 'Find a ' + target + ' by exploring locations.'
    elif stage == 'take_target':
        return 'Take the ' + target + ' from its current location.'
    elif stage == 'transform':
        if 'heat' in task_type:
            return 'Heat the ' + target + ' using microwave or stoveburner.'
        elif 'cool' in task_type:
            return 'Cool the ' + target + ' using fridge.'
        elif 'clean' in task_type:
            return 'Clean the ' + target + ' using sinkbasin.'
        return 'Apply required transformation to the item.'
    elif stage == 'go_destination':
        return 'Go to the ' + dest + ' to place the item.'
    elif stage == 'put_target':
        return 'Put the ' + target + ' in/on the ' + dest + '.'
    return None

def hook(ctx, nb):
    last_hint = nb.get('last_hint', '')
    admissible = ctx.get('admissible', [])
    hint = get_stage_hint(nb, admissible)
    if hint and hint != last_hint:
        nb['last_hint'] = hint
        return {'message': hint}
    return None
